@Override
  public @Nullable CallAdapter<?, ?> get(
      Type returnType, Annotation[] annotations, Retrofit retrofit) {
    if (getRawType(returnType) != CompletableFuture.class) {
      return null;
    }
    if (!(returnType instanceof ParameterizedType)) {
      throw new IllegalStateException(
          "CompletableFuture return type must be parameterized"
              + " as CompletableFuture<Foo> or CompletableFuture<? extends Foo>");
    }
    Type innerType = getParameterUpperBound(0, (ParameterizedType) returnType);

    if (getRawType(innerType) != Response.class) {
      // Generic type is not Response<T>. Use it for body-only adapter.
      return new BodyCallAdapter<>(innerType);
    }

    // Generic type is Response<T>. Extract T and create the Response version of the adapter.
    if (!(innerType instanceof ParameterizedType)) {
      throw new IllegalStateException(
          "Response must be parameterized" + " as Response<Foo> or Response<? extends Foo>");
    }
    Type responseType = getParameterUpperBound(0, (ParameterizedType) innerType);
    return new ResponseCallAdapter<>(responseType);
  }

BodyCallAdapter(Type responseType) {
      this.responseType = responseType;
    }

@Override
    public Type responseType() {
      return responseType;
    }

@Override
    public CompletableFuture<R> adapt(final Call<R> call) {
      final CompletableFuture<R> future =
          new CompletableFuture<R>() {
            @Override
            public boolean cancel(boolean mayInterruptIfRunning) {
              if (mayInterruptIfRunning) {
                call.cancel();
              }
              return super.cancel(mayInterruptIfRunning);
            }
          };

      call.enqueue(
          new Callback<R>() {
            @Override
            public void onResponse(Call<R> call, Response<R> response) {
              if (response.isSuccessful()) {
                future.complete(response.body());
              } else {
                future.completeExceptionally(new HttpException(response));
              }
            }

            @Override
            public void onFailure(Call<R> call, Throwable t) {
              future.completeExceptionally(t);
            }
          });

      return future;
    }

ResponseCallAdapter(Type responseType) {
      this.responseType = responseType;
    }

@Override
    public Type responseType() {
      return responseType;
    }

@Override
    public CompletableFuture<Response<R>> adapt(final Call<R> call) {
      final CompletableFuture<Response<R>> future =
          new CompletableFuture<Response<R>>() {
            @Override
            public boolean cancel(boolean mayInterruptIfRunning) {
              if (mayInterruptIfRunning) {
                call.cancel();
              }
              return super.cancel(mayInterruptIfRunning);
            }
          };

      call.enqueue(
          new Callback<R>() {
            @Override
            public void onResponse(Call<R> call, Response<R> response) {
              future.complete(response);
            }

            @Override
            public void onFailure(Call<R> call, Throwable t) {
              future.completeExceptionally(t);
            }
          });

      return future;
    }

