public Builder add(Class<? extends Annotation> cls, Converter.Factory factory) {
        if (cls == null) {
          throw new NullPointerException("cls == null");
        }
        if (factory == null) {
          throw new NullPointerException("factory == null");
        }
        factories.put(cls, factory);
        return this;
      }

