              type, parameterAnnotations, methodAnnotations, retrofit);
        }
        if (annotation instanceof Xml) {
          return xmlFactory.requestBodyConverter(
              type, parameterAnnotations, methodAnnotations, retrofit);
        }
      }
      return null;
    }

