        command -> {
          runnableRef.set(command);
          runnableLatch.countDown();
        };
    Retrofit retrofit =
        new Retrofit.Builder().baseUrl(server.url("/")).callbackExecutor(executor).build();
    CallMethod service = retrofit.create(CallMethod.class);
